  "findings": [
    {
      "model_finding_id": "F1",
      "proposition": "Prioritise a small pilot covering quick meals and flexible replanning (60.82% request help), using up food (59.16%) and budgeting (57.12%). Sharing is also requested by 47.23%, but sits 9.88–13.59 percentage points below these tasks descriptively. The three leading tasks form a shortlist, not an established winner.",
      "evidence_refs": ["analysis_results.json#/tables/needs/values"],
      "importance": "primary",
      "claim_strength": "Descriptive task demand supporting a pilot recommendation",
      "qualification": "Eligible N/weighted N=2700/2700; answered n/weighted n/ESS=2596/2595.96/2045.54 for every item. DK=80, refusal=24; 116 None respondents remain included; structural omissions=0. Multiple-response respondent incidence, not shares of mentions. Leading-task gaps are at most 3.70 points, below the 8-point attention threshold; sharing gaps exceed it, but no paired superiority tests are supplied. These requests do not establish demand for a digital product.",
      "topic_cluster": "pilot_tasks"
    },
    {
      "model_finding_id": "F2",
      "proposition": "Recruit households meeting the effort criteria as a priority pilot audience: they report 2.19 versus 0.97 top-up days per week, a +1.22-day difference (95% CI 1.10 to 1.34; Holm p=3.72e-84), and 3.73 versus 4.93 planned days, a −1.20-day difference (CI −1.36 to −1.04; Holm p=3.28e-48). Both exceed the 0.5-day attention threshold.",
      "evidence_refs": ["analysis_results.json#/tables/NEED_EFFORT_TOPUPS/values", "analysis_results.json#/tables/NEED_EFFORT_PLANNING/values"],
      "importance": "primary",
      "claim_strength": "Prespecified associations with multiplicity-adjusted p-values",
      "qualification": "Group order: criteria met/not met. Eligible N/weighted N=904/809.73 and 1642/1729.28. Top-ups valid n/weighted n/ESS=878/782.55/661.07 and 1588/1669.18/1286.98; DK/refusal=18/8 and 42/12. Planning valid bases=872/779.09/656.41 and 1586/1666.86/1285.52; DK/refusal=22/10 and 40/16. Unknown effort state=154; structural omissions=0. These external reported behaviours support recruitment, not intervention effectiveness or commercial superiority. No effort-by-quick-meal-request contrast is supplied.",
      "topic_cluster": "priority_audiences"
    },
    {
      "model_finding_id": "F3",
      "proposition": "Include budget and waste audiences alongside effort. Budget-state households report overspending at 72.31% versus 35.03%: +37.28 points (95% CI 32.70 to 41.86; Holm p=9.69e-57). Waste-state households report 1.87 versus 0.87 discard days: +1.00 day (CI 0.87 to 1.14; Holm p=1.04e-47). Matching support requests are also descriptively higher: budget help 78.13% versus 50.03% (+28.10 points), and use-up help 73.61% versus 53.23% (+20.38 points).",
      "evidence_refs": [
        "analysis_results.json#/tables/NEED_BUDGET_OVERSPEND/values",
        "analysis_results.json#/tables/NEED_WASTE_DISCARD/values",
        "analysis_results.json#/tables/support_budget_by_need_budget/values",
        "analysis_results.json#/tables/support_use_up_by_need_waste/values"
      ],
      "importance": "primary",
      "claim_strength": "Prespecified external-outcome associations, supplemented by descriptive matched support requests",
      "qualification": "All differences exceed their attention thresholds. Group order: met/not met. Budget eligible N/weighted N=717/667.29 and 1840/1896.95; outcome valid n/weighted n/ESS=678/631.58/522.17 and 1708/1769.77/1368.26; DK/refusal=33/6 and 107/25; unknown state=143. Waste eligible bases=821/775.51 and 1728/1785.80; outcome valid bases=797/754.72/615.00 and 1664/1721.13/1331.13; DK/refusal=14/10 and 41/23; unknown state=151. Structural omissions=0. Support bases and unavailable group DK/refusal splits are recorded in matched_support_requests; those contrasts have no confirmatory tests. Overspending is incidence, not money; discard counts days, not quantities. Separate within-state contrasts cannot rank overlapping audiences.",
      "topic_cluster": "priority_audiences"
    },
    {
      "model_finding_id": "F4",
      "proposition": "Recruit overlapping needs rather than exclusive personas. Effort, waste and budget criteria are met by 31.89%, 30.28% and 26.02% of their respective derivable bases. Among households with all flags valid, 58.89% meet at least one state, 24.44% meet at least two, and 5.93% meet all three.",
      "evidence_refs": [
        "analysis_results.json#/tables/need_effort/values",
        "analysis_results.json#/tables/need_waste/values",
        "analysis_results.json#/tables/need_budget/values",
        "analysis_results.json#/tables/need_combinations/values"
      ],
      "importance": "secondary",
      "claim_strength": "Descriptive joint membership",
      "qualification": "Eligible N/weighted N=2700/2700. Marginal bases, unknown counts and all eight combinations are in need_state_sizes_and_joint_membership. Joint valid n/weighted n/ESS=2280/2290.14/1799.62; 420 lack at least one flag. Marginal prevalence uses different valid denominators. Numerical prevalence differences do not establish superiority; meeting no defined state does not mean having no support needs.",
      "topic_cluster": "audience_overlap"
    },
    {
      "model_finding_id": "F5",
      "proposition": "Include households with children under 16 as a practical recruitment context. They report 1.91 versus 1.17 top-up days: +0.73 day (95% CI 0.63 to 0.84; Holm p=3.91e-40), exceeding the attention threshold. Their planning difference is smaller: 4.23 versus 4.64 days, −0.40 day (CI −0.54 to −0.27; Holm p=6.64e-9), statistically detectable but below the 0.5-day point-estimate threshold.",
      "evidence_refs": ["analysis_results.json#/tables/CHILDREN_TOPUPS/values", "analysis_results.json#/tables/CHILDREN_PLANNING/values"],
      "importance": "secondary",
      "claim_strength": "Prespecified household-context associations with multiplicity-adjusted p-values",
      "qualification": "Children/no-children eligible N/weighted N=1296/702 and 1404/1998. Top-ups valid n/weighted n/ESS=1258/681.17/1216.30 and 1356/1926.49/1273.98; DK/refusal=29/9 and 36/12. Planning valid bases=1254/679.47/1212.62 and 1355/1923.93/1272.60; DK/refusal=30/12 and 35/14. Unknown children status and structural omissions=0. Planning's interval includes differences exceeding 0.5 day in magnitude. Children status is neither a need definition nor a causal explanation.",
      "topic_cluster": "household_context"
    },
    {
      "model_finding_id": "F6",
      "proposition": "Keep participation optional and test delivery format: digital receptivity is polarised, with 46.82% agreeing, 47.38% disagreeing and 5.80% neutral. Strong agreement and strong disagreement are each about 35%; a near-midpoint mean would obscure this split.",
      "evidence_refs": ["analysis_results.json#/tables/att_digital_help_5/values"],
      "importance": "primary",
      "claim_strength": "Descriptive attitude distribution",
      "qualification": "Eligible N/weighted N=2700/2700; valid n/weighted n/ESS=2610/2609.19/2057.46; DK=67, refusal=23, structural omissions=0. Full distribution is in ordinal_distributions. This general attitude is not a tested PantryWorks concept, uptake forecast or evidence that one side exceeds the other.",
      "topic_cluster": "delivery_format"
    },
    {
      "model_finding_id": "F7",
      "proposition": "Existing users offer comparison experiences, but neither a dissatisfied replacement market nor tool effectiveness is established. Current use is 38.90%; among answering current users, 83.15% are satisfied and 54.27% have used sharing. Free recipe/list users are more digitally receptive than nonusers descriptively (61.18% versus 39.51%), yet their reported top-up days (1.32 versus 1.36) and planned days (4.59 versus 4.51) are similar in magnitude.",
      "evidence_refs": [
        "analysis_results.json#/tables/current_tool_use/values",
        "analysis_results.json#/tables/tool_satisfaction_5/values",
        "analysis_results.json#/tables/shared_list_use_28d/values",
        "analysis_results.json#/tables/profile_planning_tool_28d/values/0",
        "analysis_results.json#/tables/profile_planning_tool_28d/values/2",
        "analysis_results.json#/tables/older_paid_users/values"
      ],
      "importance": "secondary",
      "claim_strength": "Descriptive prevalence, conditional experience and selected profile comparison",
      "qualification": "Routing, full satisfaction distribution and bases are in tool_routing_and_satisfaction; profile distributions and outcome-specific bases are in selected_profile_comparisons. Satisfaction/sharing apply only to answering current users. Follow-ups are unasked for 1595 nonusers and 65 unknown screeners; the latter's DK/refusal split is unavailable. Free-tool versus nonuser differences are +21.67 points in receptivity, −0.05 top-up day and +0.09 planned day, calculated before rounding; only the receptivity gap exceeds its attention threshold. No equivalence or causal test is implied. Current users are selected. Older paid-user satisfaction remains suppressed: eligible N/weighted N=20/20.36; valid n/weighted n/ESS=18/18.27/17.73; DK=2, refusal=0.",
      "topic_cluster": "existing_tools"
    },
    {
      "model_finding_id": "F8",
      "proposition": "Test flexibility, low setup effort, acceptable cost and information-sharing controls together. Barriers are tightly grouped: rigidity 49.56%, extra cost 49.56%, privacy 48.72% and setup/upkeep 47.90%. Compare realistic delivery alternatives on task completion and burden; obtain price evidence, observed uptake, repeated use and controlled outcome evidence before commercial claims.",
      "evidence_refs": [
        "analysis_results.json#/tables/barriers/values",
        "analysis_results.json#/tables/att_digital_help_5/values",
        "analysis_results.json#/tables/needs/values"
      ],
      "importance": "primary",
      "claim_strength": "Descriptive barriers and research recommendation",
      "qualification": "Barriers eligible N/weighted N=2700/2700; answered n/weighted n/ESS=2570/2574.37/2029.07 for every item; DK=101, refusal=29, structural omissions=0. Includes 204 None respondents; multiple selections permitted. Largest gap=1.66 points, below the 8-point attention threshold; no winner is established. Recommendations are further research, not completed evidence. The study has no randomised concept exposure, price test, observed purchase, revenue or longitudinal retention evidence.",
      "topic_cluster": "pilot_design_and_evidence"
    },
    {
      "model_finding_id": "F9",
      "proposition": "Vary recruitment and delivery testing by planner age and work context. Compared with ages 35–49, planners aged 65+ report lower digital receptivity (37.49% versus 48.77%), fewer top-up days (0.97 versus 1.62) and more planned days (5.06 versus 4.32). Planners working 30+ paid hours report greater receptivity than those not in paid work (50.92% versus 40.56%) and fewer planned days (4.27 versus 4.84); their top-up difference is smaller (1.57 versus 1.12).",
      "evidence_refs": [
        "analysis_results.json#/tables/profile_age_band/values/2",
        "analysis_results.json#/tables/profile_age_band/values/4",
        "analysis_results.json#/tables/profile_work_hours_band/values/0",
        "analysis_results.json#/tables/profile_work_hours_band/values/2"
      ],
      "importance": "secondary",
      "claim_strength": "Descriptive profile contrasts supporting variation in pilot recruitment",
      "qualification": "Full digital distributions, eligible bases, outcome-specific valid bases/ESS and DK/refusal counts are in selected_profile_comparisons. Age differences are −11.28 points receptivity, −0.65 top-up day and +0.74 planned day; work differences are +10.36 points, −0.57 planned day and +0.45 top-up day. All except the work top-up difference exceed their attention thresholds. These are selected descriptive comparisons, without confirmatory tests or adjustment for other characteristics. Age/work describe the responding planner; outcomes describe the household. They overlap with children and need states, cannot be treated as independent explanations, and do not justify excluding older or nonworking planners.",
      "topic_cluster": "household_context"
    }
  ],
  "story": {
    "beats": [
      {
        "order": 1,
        "finding_refs": ["F1", "F2", "F3"],
        "headline_intent": "Pilot flexible meal help with use-up and budgeting tasks",
        "analytical_relationship": "Broad task requests establish a shortlist; external behaviours and matching support requests identify relevant recruitment audiences without proving intervention effects."
      },
      {
        "order": 2,
        "finding_refs": ["F4", "F5", "F9"],
        "headline_intent": "Recruit across overlapping needs and varied household contexts",
        "analytical_relationship": "Joint membership prevents exclusive-persona targeting; children contrasts and descriptive age/work differences refine recruitment while retaining their different inferential status."
      },
      {
        "order": 3,
        "finding_refs": ["F6", "F7"],
        "headline_intent": "Keep participation optional and delivery format open",
        "analytical_relationship": "Polarised receptivity qualifies task demand. Selected current users report high satisfaction, and greater receptivity does not establish better behavioural outcomes or a replacement opportunity."
      },
      {
        "order": 4,
